// Des: Commands sync and purge, disk-full guard, alert helper
// Flo: build the vendor pool > sync: upload with failover, then purge every layer, keepalive, verify > purge: same phases, dry-run by default > alerts go out as one mail
// I/O: Ctx (config, keys) > stdout line or JSON, exit code; dry-run never writes and never touches the network for writing
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const cpic = @import("ct-ctrl-cpic.zig"); const flow = @import("ru-clou-flow.zig"); const fail = @import("ru-fail-over.zig"); const ploc = @import("ru-purg-loca.zig"); const outb = @import("sy-clou-outb.zig"); const aler = @import("ob-aler-send.zig"); const live = @import("nt-vend-live.zig"); const pipe = @import("ru-page-fetc.zig"); const pexp = @import("ut-path-expa.zig"); const cryp = @import("ut-cryp-aead.zig");
const Info = struct { mode: []const u8, pend_file: i64, stor: []const u8, sqlv: []const u8, note: []const u8 };
const Outp = struct { recs: u32, fil2: u32, pack: []const u8, stor: []const u8, sqlv: []const u8, tris: u8, purg: u32, kept: u32, comp: u32, blan: u32, gone: u32, aged: u32, pres: u32, tras: u32, veri: u32, bads: u32, lost: u32, errs: u32, alrt: u32, mirr: bool, msto: u32, msql: u32, mque: i64, msqp: i64, mdea: u32, mfix: u32, morp: u32 };
fn contKey(ctx2: *const ctx3.Ctxz) ?[32]u8 { if (!ctx2.conf.cont_enab) return null; const keyd = pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return null; const path = std.fs.path.join(ctx2.allo, &.{ keyd, "cont.key" }) catch return null; return cryp.keyzLoad(ctx2.allo, ctx2.iozz, path) catch null; }
pub fn alerTryz(ctx2: *const ctx3.Ctxz, subj: []const u8, text: []const u8) void { const keyd = pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return; var lvzz: live.Live = .{ .time_mill = 15000 }; const alzz = aler.alerLoad(ctx2.allo, ctx2.iozz, keyd, ctx2.conf, lvzz.send(), ctx2.init.gpa); _ = aler.alerSend(&alzz, ctx2.allo, ctx2.iozz, subj, text) catch {}; }
fn alrtSend(ctx2: *const ctx3.Ctxz, fres: flow.Fres) !void { if (fres.alrt.len == 0) return; var text: std.ArrayList(u8) = .empty; for (fres.alrt) |line| { try text.appendSlice(ctx2.allo, line); try text.append(ctx2.allo, '\n'); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "warn: {s}", .{line})); } if (ctx2.args.live) alerTryz(ctx2, "scra cloud", text.items); }
fn firsName(dbzz: *@import("st-stor-sqli.zig").Dbzz, aren: std.mem.Allocator, list: anytype, nowz: i64) ![]const u8 { if (list.len == 0) return "none"; const nams = try aren.alloc([]const u8, list.len); for (list, 0..) |item, indx| nams[indx] = item.name; const indx = (try fail.failFirs(dbzz, nams, &.{}, nowz)) orelse return "none"; return nams[indx]; }
pub fn runzSync(ctx2: *const ctx3.Ctxz) !u8 { if (!ctx3.dbzzHave(ctx2)) { try ctx3.outz(ctx2, "nothing to sync yet"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const keyd = pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return error.BadConfig; var lvzz: live.Live = .{ .time_mill = ctx2.conf.fetc_time_seco * 1000 }; const hand = try cpic.handMake(ctx2, lvzz.send(), keyd); const nowz = pipe.nowzMill(ctx2.iozz);
if (!ctx2.args.live) { const info: Info = .{ .mode = "dry-run", .pend_file = try outb.outbCont(&dbzz, 0), .stor = try firsName(&dbzz, ctx2.allo, hand.stos, nowz), .sqlv = try firsName(&dbzz, ctx2.allo, hand.sqls, nowz), .note = if (ctx2.conf.clou_mirr_enab) "mirror is on: every store and database gets each run; pending counts include files, records and mirror queues; add --live to upload" else "pending counts include files and records; add --live to upload; scra purge shows the purge plan" }; try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, info, try std.fmt.allocPrint(ctx2.allo, "dry-run | {d} queued | store {s} | sql {s} | add --live to upload", .{ info.pend_file, info.stor, info.sqlv }))); return 0; }
if (hand.stos.len == 0 or hand.sqls.len == 0) return error.NotConfigured; var flwz: flow.Flow = .{ .iozz = ctx2.iozz, .dbzz = &dbzz, .dirz = ctx2.dirz, .conf = ctx2.conf, .stos = hand.stos, .sqls = hand.sqls, .ckey = contKey(ctx2) }; const fres = try flow.flowSync(&flwz, ctx2.allo, nowz); const lres = fres.loca; const outp: Outp = .{ .recs = fres.sres.recs, .fil2 = fres.sres.fil2, .pack = fres.sres.pack, .stor = fres.stor, .sqlv = fres.sqlv, .tris = fres.tris, .purg = fres.pac4, .kept = fres.kept, .comp = fres.comp, .blan = fres.blan, .gone = fres.gone, .aged = lres.aged, .pres = lres.pres, .tras = lres.tras, .veri = fres.veri.veri, .bads = fres.veri.vbad + fres.bads, .lost = fres.veri.lost, .errs = fres.errs, .alrt = @intCast(fres.alrt.len), .mirr = fres.mirr.onzz, .msto = fres.mirr.sent + fres.mirr.drai, .msql = fres.mirr.sqls, .mque = fres.mirr.left, .msqp = fres.mirr.sqlf, .mdea = fres.mirr.dead, .mfix = fres.mirr.quer + fres.mirr.bads, .morp = fres.mirr.orph };
const plai = try std.fmt.allocPrint(ctx2.allo, "sync | {d} records | {d} files in {s} | store {s} sql {s} (try {d}) | purged {d} packs ({d} kept, {d} compacted) | db blanked {d} gone {d} | local aged {d} pruned {d} trash {d} | verified {d} bad {d} lost {d}{s}", .{ outp.recs, outp.fil2, outp.pack, outp.stor, outp.sqlv, outp.tris, outp.purg, outp.kept, outp.comp, outp.blan, outp.gone, outp.aged, outp.pres, outp.tras, outp.veri, outp.bads, outp.lost, if (outp.mirr) try std.fmt.allocPrint(ctx2.allo, " | mirror {d} objects {d} statements, queued {d} + {d}, down {d}, audit fixed {d} orphans {d}", .{ outp.msto, outp.msql, outp.mque, outp.msqp, outp.mdea, outp.mfix, outp.morp }) else "" }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, outp, plai)); try alrtSend(ctx2, fres); return 0; }
pub fn runzPurg(ctx2: *const ctx3.Ctxz) !u8 { if (!ctx3.dbzzHave(ctx2)) { try ctx3.outz(ctx2, "nothing to purge yet"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const keyd = pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return error.BadConfig; var lvzz: live.Live = .{ .time_mill = ctx2.conf.fetc_time_seco * 1000 }; const hand = try cpic.handMake(ctx2, lvzz.send(), keyd); if (hand.stos.len == 0 or hand.sqls.len == 0) return error.NotConfigured; const dryz = !ctx2.args.live; var flwz: flow.Flow = .{ .iozz = ctx2.iozz, .dbzz = &dbzz, .dirz = ctx2.dirz, .conf = ctx2.conf, .stos = hand.stos, .sqls = hand.sqls, .dryz = dryz }; const fres = try flow.flowPurg(&flwz, ctx2.allo, pipe.nowzMill(ctx2.iozz)); const lres = fres.loca;
const outp: Outp = .{ .recs = 0, .fil2 = 0, .pack = "", .stor = fres.stor, .sqlv = fres.sqlv, .tris = 0, .purg = fres.pac4, .kept = fres.kept, .comp = fres.comp, .blan = fres.blan, .gone = fres.gone, .aged = lres.aged, .pres = lres.pres, .tras = lres.tras, .veri = fres.veri.veri, .bads = fres.veri.vbad + fres.bads, .lost = fres.veri.lost, .errs = fres.errs, .alrt = @intCast(fres.alrt.len), .mirr = fres.mirr.onzz, .msto = fres.mirr.sent + fres.mirr.drai, .msql = fres.mirr.sqls, .mque = fres.mirr.left, .msqp = fres.mirr.sqlf, .mdea = fres.mirr.dead, .mfix = fres.mirr.quer + fres.mirr.bads, .morp = fres.mirr.orph }; const plai = try std.fmt.allocPrint(ctx2.allo, "purge {s} | pages: {d} packs ({d} kept, {d} compacted) | db: blanked {d} gone {d} | local: aged {d} pruned {d} trash {d} log {d} outbox {d} dead {d}{s}", .{ if (dryz) "dry-run" else "live", outp.purg, outp.kept, outp.comp, outp.blan, outp.gone, outp.aged, outp.pres, outp.tras, lres.logz, lres.outb, lres.dead, if (dryz) " | add --live to run" else "" }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, outp, plai)); try alrtSend(ctx2, fres); return 0; }
pub fn diskGuar(ctx2: *const ctx3.Ctxz) !void { if (!ctx3.dbzzHave(ctx2)) return; if (!try ploc.locaFull(ctx2.allo, ctx2.iozz, ctx2.dirz, ctx2.conf)) return; alerTryz(ctx2, "scra disk full", "the data folder is at 95% of capz_disk_gbyt and fetching is paused: run scra sync --live so verified files can be pruned, or raise capz_disk_gbyt"); return error.DiskFull; }
